import base64, json, os
ARB_DATA = base64.b64decode("").decode("utf-8")
NEW_KEYS = json.loads(ARB_DATA)

FILE_RECORDER_CONTROLS_DART = base64.b64decode("").decode("utf-8")
FILE_RECORDING_ITEM_DART = base64.b64decode("").decode("utf-8")
FILE_RECORDING_LIST_DART = base64.b64decode("").decode("utf-8")
FILE_SAVE_DIALOG_DART = base64.b64decode("").decode("utf-8")
FILE_FOLDER_ITEM_DART = base64.b64decode("").decode("utf-8")
FILE_RECORDER_PAGE_DART = base64.b64decode("").decode("utf-8")

# ── Write Dart files ──
with open(r"lib\features\recorder\widgets\recorder_controls.dart", "w", encoding="utf-8", newline="\n") as f: f.write(FILE_RECORDER_CONTROLS_DART)
print("Written: lib\features\recorder\widgets\recorder_controls.dart")
with open(r"lib\features\recorder\widgets\recording_list.dart", "w", encoding="utf-8", newline="\n") as f: f.write(FILE_RECORDING_LIST_DART)
print("Written: lib\features\recorder\widgets\recording_list.dart")
with open(r"lib\features\recorder\recorder_page.dart", "w", encoding="utf-8", newline="\n") as f: f.write(FILE_RECORDER_PAGE_DART)
print("Written: lib\features\recorder\recorder_page.dart")
with open(r"lib\features\recorder\widgets\save_dialog.dart", "w", encoding="utf-8", newline="\n") as f: f.write(FILE_SAVE_DIALOG_DART)
print("Written: lib\features\recorder\widgets\save_dialog.dart")
with open(r"lib\features\recorder\widgets\folder_item.dart", "w", encoding="utf-8", newline="\n") as f: f.write(FILE_FOLDER_ITEM_DART)
print("Written: lib\features\recorder\widgets\folder_item.dart")
with open(r"lib\features\recorder\widgets\recording_item.dart", "w", encoding="utf-8", newline="\n") as f: f.write(FILE_RECORDING_ITEM_DART)
print("Written: lib\features\recorder\widgets\recording_item.dart")

# ── Update ARB files ──
for fname, keys in NEW_KEYS.items():
    fpath = os.path.join("lib", "l10n", fname)
    try:
        with open(fpath, "r", encoding="utf-8") as f: data = json.load(f)
    except: data = {}
    added = sum(1 for k in keys if k not in data)
    data.update({k:v for k,v in keys.items() if k not in data})
    with open(fpath, "w", encoding="utf-8", newline="\n") as f:
        json.dump(data, f, ensure_ascii=False, indent=2)
        f.write("\n")
    print(f"{fname}: +{added} keys")

print("\nDone! Run: flutter run")
